"""Parser tests run everywhere; filesystem safety tests require actual POSIX.

Integration fixtures live in a temporary directory under the test user's home,
not /tmp, because rejecting writable ancestors (including /tmp) is intentional.
They never access the test user's real .ssh directory.
"""

import base64
import hashlib
import json
import os
from pathlib import Path
import stat
import struct
import tempfile
from types import SimpleNamespace

import pytest

from proxyhub.host.ssh import SSHKeyError, SSHSafetyError, apply_append, parse_authorized_key, plan_append


# Generated by cryptography's real Ed25519 key generator. No private key retained.
PUBLIC = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGzcOQHT8Ia5IcddsifvNoSgKi8hrk6b5V8I3gbpQF9a"
CONTEXT = {"addr": "192.0.2.10", "host": "client.example", "laddr": "192.0.2.20", "lport": "2222"}


def _wire(*values):
    return b"".join(struct.pack(">I", len(value)) + value for value in values)


def _key(blob, algorithm="ssh-ed25519"):
    return algorithm + " " + base64.b64encode(blob).decode("ascii")


def test_real_ed25519_identity_and_fingerprint():
    parsed = parse_authorized_key(PUBLIC + " first host")
    decoded = base64.b64decode(PUBLIC.split()[1])
    assert parsed.identity == ("ssh-ed25519", decoded)
    assert parsed.fingerprint == "SHA256:" + base64.b64encode(hashlib.sha256(decoded).digest()).decode().rstrip("=")
    assert parsed.comment == "first host"
    assert parsed.options == ()
    assert parsed.identity == parse_authorized_key(PUBLIC + " different comment").identity


def test_quoted_options_follow_openssh_escape_rules():
    parsed = parse_authorized_key(r'command="printf \"hello\" C:\backup",no-pty ' + PUBLIC + " comment")
    options = dict(parsed.options)
    assert options["command"] == 'printf "hello" C:\\backup'
    assert options["pty"] == "no"
    # Backslashes do not use shell/Python escape semantics: only \" is special.
    assert dict(parse_authorized_key(r'command="a\\b" ' + PUBLIC).options)["command"] == r"a\\b"


def test_option_order_case_and_restriction_effects():
    first = parse_authorized_key('no-pty,FROM="192.0.2.0/24",no-agent-forwarding ' + PUBLIC)
    second = parse_authorized_key('no-agent-forwarding,from="192.0.2.0/24",NO-PTY ' + PUBLIC)
    assert first.options == second.options
    assert parse_authorized_key("restrict,pty " + PUBLIC).options != parse_authorized_key("pty,restrict " + PUBLIC).options
    assert parse_authorized_key("no-pty,pty " + PUBLIC).options == ()


def test_repeated_options_use_effective_values():
    first = parse_authorized_key('environment="FOO=first",environment="FOO=ignored",permitopen="a:080",permitopen="a:80" ' + PUBLIC)
    second = parse_authorized_key('permitopen="a:80",environment="FOO=first" ' + PUBLIC)
    assert first.options == second.options
    assert parse_authorized_key('permitlisten="8080" ' + PUBLIC).options == parse_authorized_key('permitlisten="*:8080" ' + PUBLIC).options
    assert parse_authorized_key('expiry-time="203001010000Z",expiry-time="20290101Z" ' + PUBLIC).options == parse_authorized_key('expiry-time="20290101000000Z" ' + PUBLIC).options


@pytest.mark.parametrize("text", [
    "-----BEGIN OPENSSH PRIVATE KEY-----", "-----BEGIN RSA PRIVATE KEY-----",
    PUBLIC + "\n", PUBLIC + "\r", PUBLIC + "\n" + PUBLIC, PUBLIC + "\x00comment",
    PUBLIC + "\x01comment", PUBLIC + "=", "", "# comment", "ssh-ed25519 !!!", "ssh-ed25519 AAAA",
])
def test_private_multiline_and_malformed_input_rejected(text):
    with pytest.raises(SSHKeyError):
        parse_authorized_key(text)


@pytest.mark.parametrize("options", [
    'command="unterminated', 'command=unquoted', 'command="a",command="b"',
    "no-pty,", "no-pty,,restrict", "unknown-option", 'no-pty="yes"',
    'command="ok"junk', 'from=""', 'environment="BAD-NAME=x"',
    'permitopen="host:0"', 'permitopen="host:65536"', 'expiry-time="20301301"',
    'tunnel="-1"', 'from="x",from="x"',
])
def test_malformed_options_rejected(options):
    with pytest.raises(SSHKeyError):
        parse_authorized_key(options + " " + PUBLIC)


@pytest.mark.parametrize("blob,algorithm", [
    (_wire(b"ssh-rsa", bytes(range(32))), "ssh-ed25519"),
    (_wire(b"ssh-ed25519", bytes(range(31))), "ssh-ed25519"),
    (_wire(b"ssh-ed25519", bytes(32)), "ssh-ed25519"),
    (_wire(b"ssh-ed25519", bytes(range(32))) + b"extra", "ssh-ed25519"),
    (_wire(b"ssh-rsa", b"\x03", b"\x7f"), "ssh-rsa"),
    (_wire(b"ecdsa-sha2-nistp256", b"nistp384", b"\x04" + bytes(64)), "ecdsa-sha2-nistp256"),
    (_wire(b"ecdsa-sha2-nistp256", b"nistp256", b"\x04" + bytes(64)), "ecdsa-sha2-nistp256"),
])
def test_malformed_or_mismatched_wire_blob_rejected(blob, algorithm):
    with pytest.raises(SSHKeyError):
        parse_authorized_key(_key(blob, algorithm))


class ConfigRunner:
    def __init__(self, paths=".ssh/authorized_keys", extra=""):
        self.paths, self.extra, self.calls = paths, extra, []
        self.on_call = None

    def __call__(self, argv):
        self.calls.append(argv)
        if self.on_call:
            self.on_call(len(self.calls))
        return "pubkeyauthentication yes\nauthorizedkeysfile " + self.paths + "\nauthorizedkeyscommand none\n" + self.extra


@pytest.fixture
def host():
    if os.name != "posix":
        pytest.skip("Requires real POSIX ownership, no-follow traversal, fsync and flock")
    with tempfile.TemporaryDirectory(prefix="proxyhub-ssh-test-", dir=Path.home()) as directory:
        home = Path(directory)
        home.chmod(0o700)
        record = SimpleNamespace(pw_name="proxyhub-test", pw_dir=str(home), pw_uid=os.getuid(), pw_gid=os.getgid())
        runner = ConfigRunner()
        yield SimpleNamespace(home=home, record=record, runner=runner, lookup=lambda name: record)


def _plan(host, text=PUBLIC, selected_path=None, context=None):
    return plan_append(host.record.pw_name, text, context or CONTEXT, selected_path,
                       runner=host.runner, account_lookup=host.lookup)


def _apply(host, plan):
    return apply_append(plan, runner=host.runner, account_lookup=host.lookup)


def _file(host, data=b"", relative=".ssh/authorized_keys", mode=0o600):
    path = host.home / relative
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    path.write_bytes(data)
    path.chmod(mode)
    return path


def test_plan_is_read_only_and_new_key_is_written_unverified(host):
    plan = _plan(host)
    assert plan["status"] == "action"
    assert not (host.home / ".ssh").exists()
    assert plan["hashes"][plan["target"]] is None
    result = _apply(host, json.loads(json.dumps(plan)))
    target = Path(plan["target"])
    assert result["status"] == "written"
    assert result["verification"] == "unverified"
    assert result["backup"] is None
    assert target.read_bytes() == PUBLIC.encode() + b"\n"
    assert stat.S_IMODE(target.stat().st_mode) == 0o600
    assert stat.S_IMODE(target.parent.stat().st_mode) == 0o700
    assert target.stat().st_uid == host.record.pw_uid
    assert target.stat().st_gid == host.record.pw_gid
    assert _plan(host)["status"] == "noop"


def test_unchanged_prefix_backup_and_stricter_mode_preserved(host):
    original = b"# legacy comment \xff\r\n\n# no final newline"
    target = _file(host, original, mode=0o400)
    result = _apply(host, _plan(host))
    assert target.read_bytes() == original + b"\n" + PUBLIC.encode() + b"\n"
    assert Path(result["backup"]).read_bytes() == original
    assert stat.S_IMODE(target.stat().st_mode) == 0o400
    assert stat.S_IMODE(Path(result["backup"]).stat().st_mode) == 0o400
    assert stat.S_IMODE(target.parent.stat().st_mode) == 0o700


def test_same_key_same_options_different_comment_is_noop(host):
    original = ('no-pty,from="192.0.2.0/24" ' + PUBLIC + " original\n").encode()
    target = _file(host, original)
    before = target.stat()
    plan = _plan(host, 'from="192.0.2.0/24",NO-PTY ' + PUBLIC + " new comment")
    assert plan["status"] == "noop"
    result = _apply(host, plan)
    assert result["status"] == "noop"
    assert result["backup"] is None
    assert target.read_bytes() == original
    assert target.stat().st_ino == before.st_ino
    assert target.stat().st_mtime_ns == before.st_mtime_ns
    assert list(target.parent.iterdir()) == [target]


def test_same_key_different_restrictions_rejected(host):
    target = _file(host, ("restrict " + PUBLIC + "\n").encode())
    with pytest.raises(SSHSafetyError, match="conflicting"):
        _plan(host)
    assert target.read_bytes().startswith(b"restrict ")


def test_effective_match_output_and_nondefault_expansion(host):
    host.runner.paths = "%h/keys/%u-%U-%%"
    plan = _plan(host)
    assert plan["target"] == str(host.home / "keys" / f"proxyhub-test-{host.record.pw_uid}-%")
    argv = host.runner.calls[0]
    assert argv[:3] == ["/usr/sbin/sshd", "-T", "-C"]
    assert "user=proxyhub-test" in argv[3]
    assert "addr=192.0.2.10" in argv[3]
    assert "host=client.example" in argv[3]
    assert "lport=2222" in argv[3]
    _apply(host, plan)
    assert Path(plan["target"]).exists()
    assert not (host.home / ".ssh").exists()


def test_multiple_effective_paths_require_selection_and_scan_all(host):
    host.runner.paths = ".ssh/authorized_keys .ssh/authorized_keys2"
    with pytest.raises(SSHSafetyError, match="explicitly select"):
        _plan(host)
    _file(host, (PUBLIC + " in second file\n").encode(), ".ssh/authorized_keys2")
    plan = _plan(host, selected_path=".ssh/authorized_keys")
    assert plan["status"] == "noop"
    assert plan["matches"][0]["path"].endswith("authorized_keys2")
    _apply(host, plan)
    assert not Path(plan["target"]).exists()


def test_literal_percent_selected_path_round_trips_through_json_plan(host):
    host.runner.paths = ".ssh/%%literal .ssh/other"
    target = host.home / ".ssh" / "%literal"
    plan = _plan(host, selected_path=str(target))
    result = _apply(host, json.loads(json.dumps(plan)))
    assert result["status"] == "written"
    assert target.read_bytes() == PUBLIC.encode() + b"\n"


def test_conflict_in_unselected_effective_file_is_rejected(host):
    host.runner.paths = ".ssh/authorized_keys .ssh/authorized_keys2"
    _file(host, (PUBLIC + "\n").encode())
    _file(host, ("no-pty " + PUBLIC + "\n").encode(), ".ssh/authorized_keys2")
    with pytest.raises(SSHSafetyError, match="conflicting"):
        _plan(host, selected_path=".ssh/authorized_keys")


@pytest.mark.parametrize("output", [
    "authorizedkeysfile none\nauthorizedkeyscommand /usr/bin/key-provider\n",
    "authorizedkeyscommand /usr/bin/key-provider\n",
    "authorizedkeysfile none .ssh/authorized_keys\n",
    "pubkeyauthentication no\nauthorizedkeysfile .ssh/authorized_keys\n",
])
def test_none_command_only_and_disabled_pubkey_have_no_fallback(host, output):
    host.runner = lambda argv: output
    with pytest.raises(SSHSafetyError):
        _plan(host)
    assert not (host.home / ".ssh").exists()


@pytest.mark.parametrize("relative", ["../authorized_keys", "%h/../authorized_keys", ".ssh/%x", ".ssh/%"])
def test_parent_traversal_and_unknown_tokens_rejected(host, relative):
    host.runner.paths = relative
    with pytest.raises(SSHSafetyError):
        _plan(host)


def test_selected_path_must_be_effective(host):
    with pytest.raises(SSHSafetyError, match="not an effective"):
        _plan(host, selected_path=".ssh/something_else")


def test_does_not_create_shared_system_parents_owned_by_target_user(host):
    outside = host.home.parent / (host.home.name + "-outside")
    host.runner.paths = str(outside / "authorized_keys")
    with pytest.raises(SSHSafetyError, match="outside the account home"):
        _plan(host)
    assert not outside.exists()


@pytest.mark.parametrize("kind", ["file", "parent", "home"])
def test_symlink_paths_rejected(host, kind):
    destination = host.home / "real"
    destination.mkdir(mode=0o700)
    if kind == "file":
        target = _file(host)
        other = host.home / "real_key"
        other.write_bytes(b"")
        other.chmod(0o600)
        target.unlink()
        target.symlink_to(other)
    elif kind == "parent":
        (host.home / ".ssh").symlink_to(destination, target_is_directory=True)
    else:
        (host.home / "home_link").symlink_to(destination, target_is_directory=True)
        host.record.pw_dir = str(host.home / "home_link")
    with pytest.raises(SSHSafetyError, match="Symlink"):
        _plan(host)


@pytest.mark.parametrize("kind,mode", [("file", 0o622), ("file", 0o700), ("parent", 0o777), ("home", 0o777)])
def test_unsafe_modes_rejected(host, kind, mode):
    target = _file(host)
    path = {"file": target, "parent": target.parent, "home": host.home}[kind]
    path.chmod(mode)
    try:
        with pytest.raises(SSHSafetyError, match="Unsafe"):
            _plan(host)
    finally:
        path.chmod(0o600 if kind == "file" else 0o700)


def test_hardlinked_key_file_rejected(host):
    target = _file(host)
    os.link(target, host.home / "other-link")
    with pytest.raises(SSHSafetyError, match="hard link"):
        _plan(host)


def test_unsafe_file_owner_rejected(host):
    if os.geteuid() != 0:
        pytest.skip("Changing test file owner requires root")
    target = _file(host)
    os.chown(target, 23456, target.stat().st_gid)
    with pytest.raises(SSHSafetyError, match="Unsafe owner"):
        _plan(host)


def test_malformed_existing_active_line_fails_closed(host):
    _file(host, b"ssh-ed25519 definitely-not-valid\n")
    with pytest.raises(SSHSafetyError, match="Cannot safely parse"):
        _plan(host)


def test_concurrent_target_change_rejects_plan(host):
    target = _file(host, b"# old\n")
    plan = _plan(host)
    target.write_bytes(b"# new\n")
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)
    assert target.read_bytes() == b"# new\n"
    assert list(target.parent.iterdir()) == [target]


def test_existing_directory_lock_blocks_competing_append(host):
    import fcntl

    target = _file(host, b"# initial\n")
    plan = _plan(host)
    descriptor = os.open(target.parent, os.O_RDONLY | os.O_DIRECTORY)
    try:
        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        with pytest.raises(SSHSafetyError, match="holds the directory lock"):
            _apply(host, plan)
    finally:
        os.close(descriptor)
    assert target.read_bytes() == b"# initial\n"


def test_concurrent_unselected_file_change_rejects_plan(host):
    host.runner.paths = ".ssh/authorized_keys .ssh/authorized_keys2"
    _file(host)
    other = _file(host, b"# old\n", ".ssh/authorized_keys2")
    plan = _plan(host, selected_path=".ssh/authorized_keys")
    other.write_bytes(b"# new\n")
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)


def test_effective_config_change_rejects_plan(host):
    plan = _plan(host)
    host.runner.extra = "passwordauthentication no\n"
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)
    assert not (host.home / ".ssh").exists()


def test_account_change_rejects_plan(host):
    plan = _plan(host)
    host.record.pw_gid += 1
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)


def test_missing_file_created_concurrently_rejects_plan(host):
    plan = _plan(host)
    _file(host, b"# concurrent creator\n")
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)


@pytest.mark.parametrize("change", ["replace", "mode"])
def test_directory_state_change_rejects_plan(host, change):
    target = _file(host)
    plan = _plan(host)
    if change == "replace":
        target.parent.rename(host.home / "old-ssh")
        _file(host)
    else:
        target.parent.chmod(0o750)
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)


def test_last_moment_change_preserves_concurrent_bytes(host):
    target = _file(host, b"# initial\n")
    plan = _plan(host)
    def mutate(call_number):
        # plan, pre-lock, post-lock, post-mkdir, pre-rename
        if call_number == 5:
            target.write_bytes(b"# concurrent writer\n")
    host.runner.on_call = mutate
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)
    assert target.read_bytes() == b"# concurrent writer\n"
    assert not list(target.parent.glob("*.tmp"))
    backups = list(target.parent.glob("*.bak"))
    assert len(backups) == 1
    assert backups[0].read_bytes() == b"# initial\n"


def test_plan_cannot_change_executable_or_target(host):
    plan = _plan(host)
    plan["effective_config"]["sshd_path"] = "/tmp/untrusted-sshd"
    with pytest.raises(SSHSafetyError, match="stale or modified"):
        _apply(host, plan)
    assert all(argv[0] == "/usr/sbin/sshd" for argv in host.runner.calls)


def test_match_context_requires_all_relevant_connection_fields(host):
    with pytest.raises(SSHSafetyError, match="requires"):
        _plan(host, context={"addr": "192.0.2.10"})
    with pytest.raises(SSHSafetyError, match="does not match"):
        _plan(host, context={**CONTEXT, "user": "different-user"})
    with pytest.raises(SSHSafetyError, match="Invalid"):
        _plan(host, context={**CONTEXT, "host": "x,user=root"})


def test_completed_process_runner_supported(host):
    original = host.runner
    host.runner = lambda argv: SimpleNamespace(stdout=original(argv), returncode=0)
    assert _plan(host)["status"] == "action"


def test_noop_plan_is_also_revalidated(host):
    target = _file(host, (PUBLIC + "\n").encode())
    plan = _plan(host)
    target.write_bytes(("restrict " + PUBLIC + "\n").encode())
    with pytest.raises(SSHSafetyError, match="conflicting"):
        _apply(host, plan)
